import re

# Read Laboratory.md for creatinine data
with open('doc/Laboratory.md', 'r') as f:
    lab = f.read()

# Read Patient.md for birth years
with open('doc/Patient.md', 'r') as f:
    patient_data = f.read()

# Extract birth years from Patient.md
patient_birthdays = {}
blocks = re.split(r'\n(?=.*Patient|.*Medical Record Number|.*file for patient)', patient_data)

for block in blocks:
    pid_match = re.search(r'Medical Record Number (\d+)|file for patient (\d+)|patient (\d+)', block, re.IGNORECASE)
    if pid_match:
        pid = pid_match.group(1) or pid_match.group(2) or pid_match.group(3)
        years = re.findall(r'(?:born|birthday|date of birth).*?(\d{4})', block, re.IGNORECASE)
        if years:
            for y in years:
                if 1800 <= int(y) <= 2000:
                    patient_birthdays[pid] = int(y)
                    break

# Extract creatinine entries from Laboratory.md
creatinine_entries = []
for m in re.finditer(r'patient (\d+)', lab, re.IGNORECASE):
    pid = m.group(1)
    start = m.end()
    end = min(start + 600, len(lab))
    snippet = lab[start:end]
    if 'creatinine' in snippet.lower():
        cr_idx = snippet.lower().find('creatinine')
        if cr_idx != -1:
            search_area = snippet[cr_idx:cr_idx+200]
            cr_match = re.search(r'([\d.]+)\s*mg/dL', search_area)
            cr = float(cr_match.group(1)) if cr_match else None
            ab = any(k in search_area.lower() for k in ['elevated', 'impaired', 'compromised', 'significantly'])
            creatinine_entries.append((pid, cr, ab))

print(f'Found {len(creatinine_entries)} creatinine entries')

# Define normal creatinine range (typical: 0.7-1.2 mg/dL)
# Abnormal = > 1.2 mg/dL OR flagged as elevated/impaired
abnormal_entries = []
for pid, cr, ab in creatinine_entries:
    if cr is not None:
        is_abnormal = (cr > 1.2) or ab
        if is_abnormal:
            abnormal_entries.append((pid, cr, ab))

print(f'Found {len(abnormal_entries)} abnormal creatinine entries')
for e in abnormal_entries[:10]:
    print(e)

# Cross-reference with birth years and calculate age (assuming current year 2024)
abnormal_under_70 = []
for pid, cr, ab in abnormal_entries:
    if pid in patient_birthdays:
        birth_year = patient_birthdays[pid]
        age = 2024 - birth_year
        if age < 70:
            abnormal_under_70.append((pid, cr, ab, age, birth_year))

print(f'\nAbnormal creatinine patients under 70: {len(abnormal_under_70)}')
for e in abnormal_under_70[:15]:
    print(f'PID: {e[0]}, Creatinine: {e[1]}, Age: {e[3]}, Birth Year: {e[4]}')

